// Functions from a legacy or C library (not declared noexcept)
void setup_legacy_resource();
void cleanup_legacy_resource();

// A modern C++ wrapper that provides a noexcept guarantee
void process_data() noexcept
{
  setup_legacy_resource();  // Assumed not to throw
  // ... perform work ...
  cleanup_legacy_resource(); // Assumed not to throw
}

// If setup_legacy_resource() were to throw an exception at runtime,
// std::terminate would be called because process_data is noexcept.
